import com.microsoft.azure.synapse.tokenlibrary.{AccessToken, TokenLibrary}

def getLSMetadata(linkServiceName: String): AccessToken = {
    val resource = s"""{"audience": "AzureDataExplorer", "name": "$linkServiceName"}"""
    TokenLibrary.getAccessToken(resource)
  }

def getNativeMetadata: AccessToken = {
    val resource = """{"audience": "AzureDataExplorer", "name": ""}"""
    TokenLibrary.getAccessToken(resource)

def unwrap_scala_option(val):
    if val is None:
        return None
    val_str = str(val)
    if val_str.startswith("Some(") and val_str.endswith(")"):
        return val_str[5:-1]
    if val_str == "None":
        return None
    return val_str

def create_random_data(num=1000):
    items_to_be_inserted = []
    for i in range(0, num):
        item = {'id': str(i) + ':' + spark.version, 'dataField1': str(i), 'dataField2': i % 2 == 0,
                'dataField3': 1.01 * i, 'dataField4': i, 'sparkVersion': spark.version}
        items_to_be_inserted.append(item)
    return items_to_be_inserted
